package com.example.dsatracker.model;import jakarta.persistence.*;import lombok.*;import java.time.LocalDateTime;@Entity@Table(name = "submissions")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builderpublic class Submission {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @ManyToOne(fetch = FetchType.LAZY, optional = false)    @JoinColumn(name = "user_id", nullable = false)    private User user;    @ManyToOne(fetch = FetchType.LAZY, optional = false)    @JoinColumn(name = "problem_id", nullable = false)    private Problem problem;    @Column(nullable = false)    private Integer attempts;    @Column(nullable = false)    private Double timeTaken;    @Column(nullable = false)    private Integer confidenceScore;    @Column(nullable = false)    private Boolean solutionViewed;    @Column(nullable = false)    private Double timeAway;    @Column(nullable = false)    private LocalDateTime solvedOn;    @Column(nullable = false)    private LocalDateTime nextRevision;}